-- Billing details for one Client (ADR-0051). drizzle-kit emits the audit value,
-- the table, ENABLE RLS, the checks, the composite foreign key, the one-row
-- index, and the audit check. The OIB function, FORCE RLS, and the grants
-- are hand-written. app.clients is not altered. There is no DELETE grant.
ALTER TYPE "app"."audit_action" ADD VALUE 'billing_details.saved';--> statement-breakpoint
-- ISO 7064 MOD 11,10. The check calls this. A volatile function cannot sit in a CHECK.
CREATE FUNCTION "app"."oib_is_valid"(value text) RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  remainder integer := 10;
  digit integer;
  total integer;
  digit_index integer;
  check_digit integer;
BEGIN
  IF value !~ '^[0-9]{11}$' THEN
    RETURN false;
  END IF;
  FOR digit_index IN 1..10 LOOP
    digit := substr(value, digit_index, 1)::integer;
    total := (digit + remainder) % 10;
    IF total = 0 THEN
      total := 10;
    END IF;
    remainder := (2 * total) % 11;
  END LOOP;
  check_digit := (11 - remainder) % 10;
  RETURN check_digit = substr(value, 11, 1)::integer;
END
$$;
